/**
 * Icon set — generated by `tools/gen-ui-art.mjs`. Do not edit by hand.
 * Icons inherit `currentColor`; size them with CSS.
 */
const raw = import.meta.glob<string>('./*.svg', { query: '?raw', import: 'default', eager: true });

export type IconName =
  | 'left'
  | 'right'
  | 'jump'
  | 'light'
  | 'heavy'
  | 'block'
  | 'dodge'
  | 'special'
  | 'pause'
  | 'sound-on'
  | 'sound-off'
  | 'music'
  | 'keyboard'
  | 'touch'
  | 'back'
  | 'check'
  | 'replay'
  | 'home'
  | 'trophy'
  | 'clock'
  | 'online'
  | 'training'
  | 'survival'
  | 'settings'
  | 'close'
  | 'up-second-wind'
  | 'up-iron-core'
  | 'up-heavy-hands'
  | 'up-quick-feet'
  | 'up-tight-guard'
  | 'up-battery'
  | 'up-deep-breath'
  | 'up-closer';

export const ICON_NAMES: readonly IconName[] = [
  'left',
  'right',
  'jump',
  'light',
  'heavy',
  'block',
  'dodge',
  'special',
  'pause',
  'sound-on',
  'sound-off',
  'music',
  'keyboard',
  'touch',
  'back',
  'check',
  'replay',
  'home',
  'trophy',
  'clock',
  'online',
  'training',
  'survival',
  'settings',
  'close',
  'up-second-wind',
  'up-iron-core',
  'up-heavy-hands',
  'up-quick-feet',
  'up-tight-guard',
  'up-battery',
  'up-deep-breath',
  'up-closer',
];

export const ICONS = {} as Record<IconName, string>;
for (const name of ICON_NAMES) ICONS[name] = raw[`./${name}.svg`] ?? '';

/** Inline SVG markup for `name`, hidden from assistive technology. */
export function icon(name: IconName, className = 'icon'): string {
  const svg = ICONS[name] ?? '';
  return svg.replace('<svg ', `<svg class="${className}" aria-hidden="true" focusable="false" `);
}
